(260, 1, 1, 'Items de contenedor', 'seccion_item', '3', 'editar', 'Se modificó un item de contenedor', '{\"id_item\":3,\"id_seccion\":4,\"id_categoria\":3,\"etiqueta\":\"\",\"icono\":null,\"titulo\":\"Llegada al campamento en Santa Lucía del Este | 7mo grado - 3er ciclo EBI\",\"titulo_linea_1\":\"\",\"titulo_linea_2\":\"\",\"titulo_linea_3\":\"\",\"subtitulo\":\"\",\"descripcion\":\"Acaban de llegar los acampantes a Santa Lucía del Este, al campamento del BHU. Los alumnos de 7.º grado de secundaria \\r\\n\\r\\nCon entusiasmo y mucha alegría, comienzan a desarrollarse  actividades de convivencia y disfrute en contacto con la naturaleza, en el entorno costero del balneario. Una experiencia única que promete ser inolvidable para todos.\",\"imagen\":\"uploads/noticias/prueba-20260601175616-511bb8.jpg\",\"imagen_mobile\":null,\"boton_1_texto\":\"Leer más\",\"boton_1_url\":\"#\",\"boton_2_texto\":\"\",\"boton_2_url\":\"\",\"url\":\"\",\"fecha_publicacion\":\"2026-05-14\",\"visible\":\"si\",\"orden\":1,\"fecha_creacion\":\"2026-04-19 19:39:21\"}', '{\"id_item\":3,\"id_seccion\":4,\"id_categoria\":3,\"etiqueta\":\"\",\"icono\":null,\"titulo\":\"Llegada al campamento en Santa Lucía del Este | 7mo grado - 3er ciclo EBI\",\"titulo_linea_1\":\"\",\"titulo_linea_2\":\"\",\"titulo_linea_3\":\"\",\"subtitulo\":\"\",\"descripcion\":\"Acaban de llegar los acampantes a Santa Lucía del Este, al campamento del BHU. Los alumnos de 7.º grado de secundaria \\r\\n\\r\\nCon entusiasmo y mucha alegría, comienzan a desarrollarse  actividades de convivencia y disfrute en contacto con la naturaleza, en el entorno costero del balneario. Una experiencia única que promete ser inolvidable para todos.\",\"imagen\":\"uploads/noticias/frontis-01-20260602113618-ed3ddb.jpg\",\"imagen_mobile\":null,\"boton_1_texto\":\"Leer más\",\"boton_1_url\":\"#\",\"boton_2_texto\":\"\",\"boton_2_url\":\"\",\"url\":\"\",\"fecha_publicacion\":\"2026-05-14\",\"visible\":\"si\",\"orden\":1,\"fecha_creacion\":\"2026-04-19 19:39:21\"}', '186.67.42.46', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/147.0.0.0 Safari/537.36 OPR/131.0.0.0', '2026-06-02 10:36:18'),
(261, 1, 1, 'Items de contenedor', 'seccion_item', '4', 'editar', 'Se modificó un item de contenedor', '{\"id_item\":4,\"id_seccion\":4,\"id_categoria\":2,\"etiqueta\":\"Etiqueta visual\",\"icono\":null,\"titulo\":\"Sofía Sabaris , estará participando en la OLAA\",\"titulo_linea_1\":\"\",\"titulo_linea_2\":\"\",\"titulo_linea_3\":\"\",\"subtitulo\":\"\",\"descripcion\":\"Sofía Sabaris, estudiante del Liceo San Pablo, estará participando en la Olimpiada Latinoamericana de Astronomía y Aeronáutica en Rio de Janeiro, Brasil (@olaa.astro).\\r\\n\\r\\nParte para Rio el 31 de agosto, junto a 4 estudiantes uruguayos más que conforman la delegación nacional, luego de haber clasificado vía las Olimpiadas Uruguayas de Astronomía y haber participado de la final de las mismas el 26 de julio de 2025 en el Planetario de Montevideo.\\r\\n\\r\\nJunto a los estudiantes viajará también Alfredo Suescun, docente de la Institución, como Co-Líder de la delegación. Él formará parte de la corrección de pruebas y también será uno de los delegados uruguayos en la asamblea de la OLAA, dónde se planificará la OLAA XVIII del próximo año.\",\"imagen\":\"uploads/noticias/prueba2-20260601175745-8c5b2e.jpg\",\"imagen_mobile\":null,\"boton_1_texto\":\"Leer más\",\"boton_1_url\":\"www.google.cl\",\"boton_2_texto\":\"\",\"boton_2_url\":\"\",\"url\":\"\",\"fecha_publicacion\":\"2025-09-03\",\"visible\":\"si\",\"orden\":2,\"fecha_creacion\":\"2026-04-19 19:39:21\"}', '{\"id_item\":4,\"id_seccion\":4,\"id_categoria\":2,\"etiqueta\":\"Etiqueta visual\",\"icono\":null,\"titulo\":\"Sofía Sabaris , estará participando en la OLAA\",\"titulo_linea_1\":\"\",\"titulo_linea_2\":\"\",\"titulo_linea_3\":\"\",\"subtitulo\":\"\",\"descripcion\":\"Sofía Sabaris, estudiante del Liceo San Pablo, estará participando en la Olimpiada Latinoamericana de Astronomía y Aeronáutica en Rio de Janeiro, Brasil (@olaa.astro).\\r\\n\\r\\nParte para Rio el 31 de agosto, junto a 4 estudiantes uruguayos más que conforman la delegación nacional, luego de haber clasificado vía las Olimpiadas Uruguayas de Astronomía y haber participado de la final de las mismas el 26 de julio de 2025 en el Planetario de Montevideo.\\r\\n\\r\\nJunto a los estudiantes viajará también Alfredo Suescun, docente de la Institución, como Co-Líder de la delegación. Él formará parte de la corrección de pruebas y también será uno de los delegados uruguayos en la asamblea de la OLAA, dónde se planificará la OLAA XVIII del próximo año.\",\"imagen\":\"uploads/noticias/frontis-07-20260602113636-fd2631.jpg\",\"imagen_mobile\":null,\"boton_1_texto\":\"Leer más\",\"boton_1_url\":\"www.google.cl\",\"boton_2_texto\":\"\",\"boton_2_url\":\"\",\"url\":\"\",\"fecha_publicacion\":\"2025-09-03\",\"visible\":\"si\",\"orden\":2,\"fecha_creacion\":\"2026-04-19 19:39:21\"}', '186.67.42.46', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/147.0.0.0 Safari/537.36 OPR/131.0.0.0', '2026-06-02 10:36:36'),
