INSERT INTO `seccion_item` (`id_item`, `id_seccion`, `id_categoria`, `etiqueta`, `icono`, `titulo`, `titulo_linea_1`, `titulo_linea_2`, `titulo_linea_3`, `subtitulo`, `descripcion`, `imagen`, `imagen_mobile`, `boton_1_texto`, `boton_1_url`, `boton_2_texto`, `boton_2_url`, `url`, `fecha_publicacion`, `visible`, `orden`, `fecha_creacion`) VALUES
(1, 3, NULL, 'exequiel Alarado', NULL, '', 'Disfrutamos', 'Creciendo', 'Contigo', '', '', 'uploads/secciones/hero_principal/4-20260606183011-b90d23.png', NULL, 'Ver galería', '#galeria', 'Nuestro equipo', '#equipo', '', NULL, 'si', 5, '2026-04-19 19:39:21'),
(2, 3, NULL, 'Nuestra Misión', NULL, '', 'Caminamos', 'Juntos', 'Quien Enseña con Amor Educa Para Siempre', '', 'Quien Enseña con Amor Educa Para Siempre', 'uploads/secciones/hero_principal/2-20260606182911-9818c7.png', 'uploads/secciones/hero_principal/lupe-y-papa-20260420084202-2b38c7.jpg', 'Ver novedades', '#noticias', 'Acceso Mi San Pablo', '#portal', '', NULL, 'si', 1, '2026-04-19 19:39:21'),
(3, 4, NULL, '', NULL, 'Campamento Anual de 7mo Grado: Tres días de crecimiento, naturaleza y amistad en Santa Lucía del Este', '', '', '', '', 'Los alumnos disfrutaron de una experiencia inolvidable centrada en el compañerismo, la reflexión y el contacto con el entorno natural, regresando con el corazón renovado y listos para los desafíos del año.\r\n\r\nEn el marco de nuestras actividades de integración y formación integral, los alumnos de 7mo grado del Colegio San Pablo vivieron su esperado Campamento Anual en el hermoso entorno de Santa Lucía del Este.\r\n\r\nEsta experiencia, que ya es un hito tradicional en el recorrido escolar de nuestros estudiantes, estuvo diseñada para ofrecer un espacio de desconexión de la rutina diaria y una reconexión profunda con la naturaleza, los valores institucionales y, sobre todo, con sus pares.\r\n\r\nEl compañerismo como protagonista\r\nDurante las jornadas, los chicos participaron en diversas dinámicas grupales, juegos de liderazgo, fogones y actividades al aire libre que desafiaron su creatividad y su capacidad de trabajo en equipo. El gran protagonista de cada actividad fue el compañerismo; la empatía y el apoyo mutuo se hicieron presentes en cada desafío superado.\r\n\r\nAdemás de la diversión, el campamento contó con momentos especialmente dedicados a la reflexión personal y grupal. Estos talleres permitieron a los alumnos conversar sobre el inicio de esta nueva etapa escolar, fortalecer sus lazos de amistad y proyectar juntos sus metas para el resto del año.\r\n\r\nUna mochila llena de recuerdos\r\nLa convivencia compartida, las charlas bajo las estrellas y las risas compartidas consolidaron un grupo más unido y fortalecido. Hoy volvemos al colegio con la mochila llena de recuerdos inolvidables, anécdotas que perdurarán en el tiempo y el corazón renovado para continuar transitando este año juntos.\r\n\r\nAgradecemos especialmente al equipo de docentes, coordinadores y animadores que hicieron posible esta enriquecedora experiencia, cuidando cada detalle para que fuera segura, divertida y profundamente significativa para nuestros alumnos.\r\n\r\n¡Felicitaciones a la generación de 7mo grado por su excelente conducta y entusiasmo durante todo el campamento!', 'uploads/noticias/foto-nota-20260606165955-a27ebc.png', NULL, '', '', '', '', '', '2026-05-13', 'si', 2, '2026-04-19 19:39:21'),
(4, 4, NULL, 'Etiqueta visual', NULL, 'De las aulas a la obra: Exalumna de la Generación 2020 lidera la histórica remodelación de nuestro gimnasio', '', '', '', '', 'La Ingeniera Civil Catalina Wensko está al frente del ambicioso proyecto de infraestructura que transformará más de 3.600 m² del Colegio San Pablo, creando espacios modernos y conectados para el deporte, el arte y la convivencia.\r\n\r\nEn el Colegio San Pablo nos llena de orgullo ver cómo nuestros egresados transforman el mundo con sus profesiones, pero la alegría es doble cuando ese talento vuelve a casa para contribuir directamente al crecimiento de nuestra propia comunidad.\r\n\r\nTenemos el enorme agrado de presentar a la Ingeniera Civil Catalina Wensko, integrante de la generación de graduados del año 2020, quien ha asumido el rol de Jefa de Obra en el proyecto de remodelación y ampliación de nuestro gimnasio institucional.\r\n\r\nPara nuestra casa de estudios, contar con la experiencia y el compromiso de una exalumna en un proyecto de esta envergadura es el testimonio más claro del lazo indestructible que une a nuestros estudiantes con la institución.\r\n\r\nUna transformación de más de 3.600 m² para toda la comunidad\r\nEste ambicioso proyecto de infraestructura marcará un antes y un después en el día a día de nuestra comunidad educativa. La obra contempla la intervención de más de 3.600 m² de nuevos espacios, diseñados bajo los más altos estándares constructivos y arquitectónicos.\r\n\r\nEntre las principales innovaciones de la obra se destacan:\r\n\r\nPolideportivo de vanguardia: Espacios optimizados y modernos pensados para potenciar el desarrollo deportivo y el bienestar físico de los alumnos de todos los niveles.\r\n\r\nÁreas destinadas al arte: Nuevos entornos específicamente acondicionados para la expresión artística y cultural, promoviendo el talento creativo de nuestros estudiantes.\r\n\r\nMayor integración y conectividad: Un rediseño integral que conectará mejor los patios, eliminando barreras visuales y generando espacios comunes mucho más amplios, seguros e integrados para el disfrute de toda la comunidad.\r\n\r\nEl orgullo de seguir creciendo juntos\r\nLa incorporación de Catalina al frente de esta obra no solo garantiza rigurosidad técnica, sino también un profundo conocimiento y cariño por la identidad del Colegio San Pablo, asegurando que cada rincón renovado conserve la esencia de nuestra institución.\r\n\r\nAgradecemos profundamente a Catalina por aceptar este gran desafío profesional y por volcar su capacidad en beneficio de las futuras generaciones de alumnos. Desde ya, le deseamos el mayor de los éxitos en cada una de las etapas de esta construcción.\r\n\r\n¡Gracias por seguir siendo parte fundamental del crecimiento del Colegio San Pablo, Catalina!', 'uploads/noticias/alejandra-constructora-20260606174025-945343.png', NULL, '', '', '', '', '', '2026-05-05', 'si', 3, '2026-04-19 19:39:21'),
(6, 4, NULL, '', NULL, 'Solidaridad en acción: Alumnos y exalumnos del Colegio San Pablo se unieron como voluntarios en la Peluffo 2026', '', '', '', '', 'Estudiantes de 9º grado, Bachillerato y egresados de nuestra institución unieron esfuerzos en una conmovedora jornada de voluntariado, reafirmando el compromiso social y los valores humanos de nuestra comunidad.\r\n\r\nEl compromiso con el prójimo y la empatía son pilares fundamentales en la propuesta educativa del Colegio San Pablo. Una vez más, nuestra comunidad demostró que la solidaridad se vive con acciones concretas, participando activamente en la edición de la Peluffo 2026.\r\n\r\nEste año, la convocatoria tuvo una respuesta sumamente especial. Una gran delegación integrada por alumnos de 9º grado, estudiantes de Bachillerato y exalumnos de la institución se sumaron como voluntarios, uniendo a distintas generaciones del colegio bajo una misma causa: apoyar el valioso trabajo que la fundación realiza por la salud y el bienestar de tantos niños y familias.\r\n\r\nUna experiencia de aprendizaje y unión grupal\r\nMás allá de la tarea realizada, las jornadas de voluntariado representan para nuestros jóvenes una auténtica experiencia de crecimiento personal. El contacto directo con la realidad y la posibilidad de brindar su tiempo de manera desinteresada les permite desarrollar habilidades socioemocionales clave, como la escucha activa, la resiliencia y el trabajo en equipo.\r\n\r\nEl ambiente de la jornada estuvo marcado por la alegría, el entusiasmo y un fuerte sentido de pertenencia. Para los alumnos actuales, compartir el día con los exalumnos significó un valioso intercambio, demostrando que el espíritu solidario del Colegio San Pablo permanece intacto incluso después de egresar de las aulas.\r\n\r\nEl orgullo de una comunidad comprometida\r\nRegresamos de esta jornada con el corazón lleno de gratitud y con el orgullo de ver el entusiasmo y los valores con los que nuestros jóvenes representan a la institución. Cada sonrisa compartida y cada esfuerzo entregado sumaron para hacer de esta edición un éxito colectivo.\r\n\r\nAgradecemos profundamente a cada uno de los estudiantes y egresados que pusieron su granito de arena, así como a los docentes y coordinadores que acompañaron y organizaron la actividad, haciendo posible que el lema de \"corazones en acción\" se hiciera realidad.\r\n\r\n¡Muchas gracias a todos por ser un verdadero ejemplo de solidaridad y comunidad!', 'uploads/noticias/la-peluffo-20260606175836-aa2d37.png', NULL, '', '', '', '', '', '2026-05-04', 'si', 4, '2026-04-19 19:39:21'),
(7, 5, NULL, NULL, NULL, '¿Cuánto dura el proceso de admisión?', NULL, NULL, NULL, NULL, 'Nuestro equipo acompaña a las familias con información clara, apoyo cercano y un proceso educativo pensado para el desarrollo integral de cada estudiante.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'si', 1, '2026-04-19 19:39:21'),
(8, 5, NULL, NULL, NULL, '¿Qué incluye la propuesta educativa?', NULL, NULL, NULL, NULL, 'Incluye acompañamiento cercano, formación en valores y una propuesta académica integral para cada etapa.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'si', 2, '2026-04-19 19:39:21'),
(11, 4, NULL, '', NULL, 'Alumna del Colegio San Pablo es premiada por Cambridge debido a su excelencia académica en los exámenes IGCSE', '', '', '', '', 'Ana Clara Boggia recibió una distinción especial por sus sobresalientes calificaciones en Literatura y Física. La ceremonia oficial contó con la participación del Embajador Británico en Uruguay, Malcolm Green.\r\n\r\nCon profundo orgullo y alegría, la comunidad educativa del Colegio San Pablo celebra el destacado reconocimiento internacional otorgado a nuestra alumna Ana Clara Boggia por parte de Cambridge.\r\n\r\nAna Clara fue distinguida con un premio especial en mérito a sus altos logros académicos en las asignaturas de Literatura y Física, correspondientes a los exámenes internacionales International General Certificate of Secondary Education (IGCSE). Este reconocimiento refleja no solo su talento y dedicación constante, sino también el fruto del esfuerzo compartido junto a su familia y al cuerpo docente de nuestra institución.\r\n\r\nUna ceremonia de distinción internacional\r\nEl galardón fue entregado en el marco de una solemne ceremonia oficial que reunió a las principales autoridades educativas del país. El evento contó con la participación de honor del Embajador de Gran Bretaña en Uruguay, Sr. Malcolm Green, quien felicitó personalmente a los estudiantes destacados y resaltó la importancia de la educación bilingüe y la excelencia académica en el desarrollo global de los jóvenes.\r\n\r\nPara el Colegio San Pablo, la obtención de estos méritos a nivel internacional consolida nuestra misión de brindar una educación con estándares globales, potenciando las capacidades analíticas, científicas y humanísticas de cada uno de nuestros alumnos.\r\n\r\nHacemos extensivo nuestro más cálido saludo a Ana Clara por este merecido logro, que inspira a toda nuestra comunidad escolar a seguir transitando el camino del esfuerzo y la super excelencia académica.\r\n\r\n¡Muchas felicidades, Ana Clara! ¡El Colegio San Pablo celebra contigo!', 'uploads/noticias/whatsapp-image-2026-06-01-at-7-13-54-pm-20260606165443-35813e.jpeg', NULL, '', '', '', '', '', '2026-04-24', 'si', 1, '2026-04-19 22:11:28'),
